
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_llp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_llp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.318582845374880e+00, -4.236785993375515e+00, -4.122255830391187e+00, -3.963784474661864e+00, -3.748225332783710e+00, -3.462118219903058e+00, -3.095480279025367e+00, -2.648532393910361e+00, -2.140301475997467e+00, -1.610828123725812e+00, -1.093947587726246e+00, -7.110326429274355e-01, -6.038055332367660e-01, -5.031498455281904e-01, -3.712521713660621e-01, -2.460734189980491e-01, -1.533836094457307e-01, -9.397555166894737e-02, -5.936431260571130e-02, -4.048590297047139e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


